from datetime import date
HOLI = {date(2026, 11, 26), date(2026, 12, 25), date(2027, 1, 1), date(2027, 1, 18)}
EARLY = {date(2026, 11, 27): "13:00", date(2026, 12, 24): "13:00"}

def session_of(d):
    if d.weekday() >= 5:
        return "주말 — 휴장"
    if d in HOLI:
        return "휴장"
    if d in EARLY:
        return "조기 마감(정규장 " + EARLY[d] + " ET 종료)"
    return "정상(정규장 16:00 ET 종료)"

for d in [date(2026, 11, 26), date(2026, 11, 27), date(2026, 11, 30), date(2026, 12, 24), date(2027, 1, 18)]:
    print(d, session_of(d))

# 출력
# 2026-11-26 휴장
# 2026-11-27 조기 마감(정규장 13:00 ET 종료)
# 2026-11-30 정상(정규장 16:00 ET 종료)
# 2026-12-24 조기 마감(정규장 13:00 ET 종료)
# 2027-01-18 휴장

order = {"qty": 100, "cum": 0, "status": "NEW", "seen": set()}

def on_exec(o, exec_id, last_qty):
    if exec_id in o["seen"]:
        return "중복 무시"
    o["seen"].add(exec_id)
    o["cum"] += last_qty
    o["status"] = "FILLED" if o["cum"] == o["qty"] else "PARTIALLY_FILLED"
    return "%s cum=%d leaves=%d" % (o["status"], o["cum"], o["qty"] - o["cum"])

for e, q in [("E1", 30), ("E2", 50), ("E2", 50), ("E3", 20)]:
    print(e, q, "->", on_exec(order, e, q))

# 출력
# E1 30 -> PARTIALLY_FILLED cum=30 leaves=70
# E2 50 -> PARTIALLY_FILLED cum=80 leaves=20
# E2 50 -> 중복 무시
# E3 20 -> FILLED cum=100 leaves=0
